templates.template:
.p-main-inner > .p-main-header {display: none;}

.p-content {
	table-layout: fixed;
	display: flex;
	flex-wrap: wrap;
	justify-content: space-between;
	width: 100%;
	max-width: 100%;
	margin-bottom: auto;
	min-height: 1px;

	.p-main-header {
		width: 100%;

		.uixpro-logo {
			width: 52px;
			height: 52px;
		}
	}

	.MainContent {
		width: ~"calc(100% - 270px)";
		max-width: ~"calc(100% - 270px)";
		display: inline-block;
	}

	.MainSidebar {
		display: inline-block;
		vertical-align: top;
		width: 250px;

		.links a {
			color: black;

			.fa {
				color: @xf-linkColor;
				width: 25px;
			}
		}
	}
}

.block--summary {
	.block-body {
		display: flex;
		width: 100%;
	}

	.left {
		padding: @xf-paddingLarge;
		width: 30%;
		border-right: 1px solid @xf-borderColor;

		span {
			color: @xf-textColorMuted;
			display: block;

			&.letterGrade {
				font-size: 47px;
			}

			&.letterGradeHint {
				font-size: 16px;
			}

			&.letterGradeDesc {
				font-size: 12px;
			}
		}
	}

	.right {
		padding: @xf-paddingLarge;
		width: 70%;
		align-items: center;

		display: flex;

		.aggregate {
			flex-grow: 1;
			text-align: center;
			vertical-align: middle;

			.muted {
				font-size: 14px;
				display: block;
				color: @xf-textColorMuted;
			}

			.count {
				display: block;
				font-size: 54px;
				line-height: 1em;
			}

			&--error {
				color: #e53935;
			}

			&--warning {
				color: #ffb300;
			}

			&--general {
				color: #9e9e9e;
			}

			&--resolved {
				color: #4caf50;
			}
		}
	}
}

.handyplan {
	background: linear-gradient(224.8deg, rgb(108, 221, 119) 0%, rgb(59, 184, 210) 100%);
	text-align: center;

	&--logo {
		width: 75px;
		height: 75px;
		margin-top: 2 * @xf-paddingLarge;
		box-shadow: 0 5px 30px rgba(0,0,0,.1);
		border-radius: 100%;
	}

	&--title {
		color: #fff;
		font-size: 24px;
		margin: 0;
		padding: 0;
	}

	&--desc {
		color: #fff;
		margin-bottom: @xf-paddingLarge;
	}

	&--get {
		margin-bottom: 2 * @xf-paddingLarge;
		font-weight: bold;
		border: none !important;
	}
}

.dataList {
	.dataList-cell {
		vertical-align: top;
	}

	.dataList-cell:nth-child(1) {
		border-left: 3px solid #9e9e9e;

		.fa {
			color: #9e9e9e;
			font-size: 20px;
		}

		&.cell--error {
			border-left-color: #e53935;

			.fa {
				color: #e53935
			}
		}

		&.cell--warning {
			border-left-color: #ffb300;

			.fa {
				color: #ffb300
			}
		}

		&.cell--resolved {
			border-left-color: #4caf50;

			.fa {
				color: #4caf50
			}
		}
	}

	.cell--action {
		text-align: right;

		.button {
			border-radius: 0;
			border: none;

			&.button--automated {
				cursor: inherit;
				background: #9e9e9e;
			}

			&.button--resolve {
				background: #4caf50;
			}
		}
	}

	.dataList-mainRow {
		max-height: none;
		white-space: normal;

		.dataList-hint {
			display: block;
		}
	}

	.score {
		font-size: 14px;
		padding-top: @xf-paddingMedium;
		color: @xf-textColorMuted;

		.score--error {
			color: #e53935
		}

		.score--warning {
			color: #ffb300
		}

		.score--resolved {
			color: #4caf50
		}
	}
}

@-webkit-keyframes shimmer {
	0% {background-position: -4rem top;}
	70% {background-position: 12.5rem top;}
	100% {background-position: 12.5rem top;}
}

.letterGrade,
.letterGradeHint {
	&--S {
		background: goldenrod -webkit-gradient(linear, 100% 0, 0 0, from(goldenrod), color-stop(0.5, palegoldenrod), to(goldenrod));
		background-position: -4rem top;
		background-repeat: no-repeat;
		-webkit-background-clip: text;
		-webkit-text-fill-color: transparent;
		-webkit-animation-name: shimmer;
		-webkit-animation-duration: 5s;
		-webkit-animation-iteration-count: infinite;
		-webkit-background-size: 4rem 100%;
	}

	&--A {
		color: #4caf50 !important;
	}

	&--B {
		color: #4caf50 !important;
	}

	&--C {
		color: #A6B128 !important;
	}

	&--D {
		color: #ffb300 !important;
	}

	&--F {
		color: #e53935 !important;
	}
}

.cell--checkbox  {
	width: 20px;
}
